const T=48;
export function environmentFor(s){if(s.biome)return s.biome;const identity=String(s.originId||'');if(/rook-regulator|brass-rail/.test(identity))return{ground:6,border:6,style:'foundry',color:'#493d38'};if(/iona-lowbank|riven-tide/.test(identity))return{ground:7,border:3,style:'riverbank',color:'#426474'};if(identity==='veyr-storm')return{ground:3,border:3,style:'storm',color:'#4d6075'};const key=s.key||'',chapter=s.chapter||1;if(/forest|grove|sanctuary/.test(key))return {ground:1,border:4,style:'woodland',color:'#324e38'};if(/river|lowbank|flood|storm|anchorage/.test(key))return{ground:7,border:3,style:'riverbank',color:'#426474'};if(/summit|lens|vent|reactor/.test(key)||s.theme===3)return{ground:3,border:3,style:'highland',color:'#4d6075'};if(/security|console|workshop|catwalk|office|hold|depot/.test(key))return{ground:6,border:6,style:'foundry',color:'#493d38'};if(s.theme===2)return{ground:2,border:4,style:'ruins',color:'#514d61'};if(key==='field')return[{ground:1,border:4,style:'woodland',color:'#324e38'},{ground:7,border:3,style:'riverbank',color:'#426474'},{ground:2,border:4,style:'ruins',color:'#514d61'}][chapter%3];return{ground:0,border:5,style:'village',color:'#4c5940'};}
export function groundPatch(c,atlas,index,x,y,n){const sw=atlas.width/4,sh=atlas.height/2,ix=index%4,iy=Math.floor(index/4),part=1/4,sx=((x%4+4)%4)/4,sy=((y%4+4)%4)/4;c.drawImage(atlas,(ix+sx)*sw,(iy+sy)*sh,sw*part,sh*part,x*T,y*T,T+1,T+1);}
export function edgeDetail(c,x,y,n,style,time){c.save();c.translate((x+.5)*T,(y+1)*T);if(style==='woodland'||style==='village'){c.strokeStyle=style==='village'?'#72804b':'#385338';c.lineWidth=2;for(let i=0;i<7;i++){const px=-22+i*7;c.beginPath();c.moveTo(px,1);c.quadraticCurveTo(px-7,-11,px+Math.sin(i)*5,-22-n%13);c.stroke();}if(n%3===0){c.fillStyle=['#f0d09a','#cc849b','#a7bca0'][n%3];for(let i=0;i<5;i++){c.beginPath();c.arc(-16+i*8,-12-(i%2)*9,2.8,0,7);c.fill();}}}else{c.fillStyle=style==='highland'?'#74808e':style==='ruins'?'#817a88':'#746b5b';c.strokeStyle='#242d3444';c.lineWidth=2;c.beginPath();c.moveTo(-22,0);c.lineTo(-17,-15);c.lineTo(-3,-26-n%12);c.lineTo(16,-17);c.lineTo(24,0);c.closePath();c.fill();c.stroke();c.fillStyle=style==='highland'?'#d6e5e6':'#b4a68b';c.beginPath();c.moveTo(-17,-15);c.lineTo(-3,-26-n%12);c.lineTo(13,-18);c.lineTo(0,-16);c.fill();}c.restore();}
export function roomSurface(c,key,x,y){const px=x*T,py=y*T;if(/clinic|chapel|crypt|vault/.test(key)){c.fillStyle=key==='clinic'?((x+y)%2?'#c5cbb5':'#a7b5a5'):((x+y)%2?'#8b8790':'#777783');c.fillRect(px,py,T,T);c.strokeStyle='#393b3b33';c.lineWidth=2;c.strokeRect(px+2,py+2,44,44);if(key==='clinic'){c.fillStyle='#698e7922';c.beginPath();c.arc(px+24,py+24,9,0,7);c.fill();}}else if(/security|console|reactor|workshop|instrumentworks|depot/.test(key)){c.fillStyle=/workshop|instrument/.test(key)?'#675a49':'#53626a';c.fillRect(px,py,T,T);c.strokeStyle='#1f2b2d77';c.lineWidth=2;c.strokeRect(px+1,py+1,46,46);c.fillStyle='#a2a48c';for(const dx of[5,43])for(const dy of[5,43])c.fillRect(px+dx,py+dy,2,2);if((x+y)%5===0){c.strokeStyle='#b9a76744';c.beginPath();c.moveTo(px+9,py+39);c.lineTo(px+39,py+9);c.stroke();}}else if(/guild|inn/.test(key)&&x%5<2){c.fillStyle=key==='guild'?'#5d536a':'#884c45';c.fillRect(px,py,T,T);c.strokeStyle='#d0af6c77';c.lineWidth=2;c.beginPath();c.moveTo(px+4,py);c.lineTo(px+4,py+48);c.stroke();}}
